package backoff

import (
	"testing"
	"time"
)

func TestExponentialBackoff(t *testing.T) {
	bc := Exponential{
		BaseDelay:  100 * time.Millisecond,
		Multiplier: 2,
		Jitter:     0,
		MaxDelay:   500 * time.Millisecond,
	}
	tests := []struct {
		retries int
		want    time.Duration
	}{
		{retries: 0, want: 100 * time.Millisecond},
		{retries: 1, want: 200 * time.Millisecond},
		{retries: 2, want: 400 * time.Millisecond},
		{retries: 3, want: 500 * time.Millisecond},
	}
	for _, test := range tests {
		if got := bc.Backoff(test.retries); got != test.want {
			t.Errorf("Backoff(%d) = %v, want %v", test.retries, got, test.want)
		}
	}
}
